declare(strict_types=1);
session_start();
if (empty($_SESSION['demo_logged_in'])) {
    header('Location: login.php');
    exit;
}
$period = $_GET['period'] ?? '30d';
$validPeriods = ['7d' => 7, '30d' => 30, '90d' => 90, '365d' => 365];
if (!isset($validPeriods[$period])) $period = '30d';
$days = $validPeriods[$period];
$end = new DateTimeImmutable('today');
$start = $end->modify('-' . ($days - 1) . ' days');
$seedValues = [30 => [12458, 186, 1250, 3.8], 7 => [3192, 49, 300, 3.5], 90 => [36714, 534, 3610, 4.1], 365 => [145890, 2180, 14270, 4.0]];
[$visitors, $enquiries, $spend, $conversion] = $seedValues[$days];
$traffic = [];
$points = 15;
for ($i = 0; $i < $points; $i++) {
    $traffic[] = round((200 + $i * 19 + sin($i * 1.75) * 78 + cos($i * 2.37) * 32) * ($days === 7 ? .8 : 1));
}
$sourceNames = ['Organic Search', 'Direct', 'Social Media', 'Paid Search', 'Referral', 'Other'];
$sourceShares = [42.5, 22.1, 12.4, 11.2, 6.8, 5.0];
$sourceColors = ['#3477f6','#5bbcd5','#35b795','#ffb34f','#8d78db','#ef7293'];
function js($value) { return json_encode($value, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); }
?>
