<script>
const values=<?= js($traffic) ?>, visitors=<?= js($visitors) ?>, enquiries=<?= js($enquiries) ?>, spend=<?= js($spend) ?>, conversion=<?= js($conversion) ?>;
const shares=<?= js($sourceShares) ?>, colors=<?= js($sourceColors) ?>;
let angle=0;const parts=shares.map((share,i)=>{const a=angle;angle+=share;return `${colors[i]} ${a}% ${angle}%`;});document.getElementById('donut').style.background=`conic-gradient(${parts.join(',')})`;
const svg=document.getElementById('lineChart'),NS='http://www.w3.org/2000/svg';function add(tag,attrs,text){let el=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));if(text!==undefined)el.textContent=text;svg.appendChild(el);return el;}
const max=Math.ceil(Math.max(...values)/100)*100;for(let j=0;j<=4;j++){let y=20+j*52;add('line',{x1:40,y1:y,x2:588,y2:y,class:'gridline'});add('text',{x:33,y:y+4,'text-anchor':'end',class:'axis'},Math.round(max*(4-j)/4).toLocaleString());}
let coords=values.map((v,i)=>[40+i*548/(values.length-1),228-v/max*205]);let line=coords.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');add('path',{d:`${line} L588,228 L40,228 Z`,class:'area'});add('path',{d:line,class:'line'});
for(let i=0;i<4;i++){const x=40+i*548/3;add('text',{x,y:253,'text-anchor':i===0?'start':i===3?'end':'middle',class:'axis'},['<?= $start->format('M j') ?>','Week 2','Week 3','<?= $end->format('M j') ?>'][i]);}
function selectPeriod(e){location.href='?period='+encodeURIComponent(e.target.value)}document.getElementById('topPeriod').addEventListener('change',selectPeriod);document.getElementById('sourcePeriod').addEventListener('change',selectPeriod);
function toggleNav(){document.getElementById('sidebar').classList.toggle('open');document.getElementById('overlay').classList.toggle('open')}
document.querySelectorAll('.nav').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.querySelectorAll('.nav').forEach(el=>el.classList.remove('active'));a.classList.add('active');if(a.dataset.section!=='Dashboard'){alert(a.dataset.section+' module is a UI placeholder. Connect your module here.');}else document.getElementById('pageTitle').textContent='Dashboard Overview';if(innerWidth<740)toggleNav();}));
document.getElementById('export').addEventListener('click',()=>{let data=[['Metric','Value'],['Website Visitors',visitors],['Total Enquiries',enquiries],['Ad Spend USD',spend],['Conversions %',conversion],[''],['Source','Share %'],...<?= js(array_map(fn($n,$i)=>[$n,$sourceShares[$i]],$sourceNames,array_keys($sourceNames))) ?>];let csv=data.map(row=>row.join(',')).join('\n');let blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='marketingpro-demo-report.csv';a.click();URL.revokeObjectURL(url)});
